#include <stdio.h>
typedef struct { char ten[50]; int tuoi; } Nguoi;
int main(void) {
    Nguoi p;
    if (scanf("%49s %d", p.ten, &p.tuoi) != 2) return 1;
    printf("%s (%d)\n", p.ten, p.tuoi);
    return 0;
}
